{
  "findings": [
    {
      "check_id": "CKV_AWS_2",
      "title": "Load Balancer Listener uses HTTP instead of HTTPS",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "HIGH",
      "explanation": "The listener is configured to use the HTTP protocol on port 80, which transmits data in cleartext. This exposes traffic to eavesdropping and man-in-the-middle attacks; it should be redirected to HTTPS or replaced with an HTTPS listener."
    }
  ],
  "patched_code": "resource \"aws_lb_listener\" \"webserver_listner\" {\n  load_balancer_arn = aws_lb.levelup-load-balancer.arn\n  port              = \"80\"\n  protocol          = \"HTTP\"\n  default_action {\n    type             = \"redirect\"\n    redirect {\n      port        = \"443\"\n      protocol    = \"HTTPS\"\n      status_code = \"HTTP_301\"\n    }\n  }\n}",
  "fix_summary": "Changed the default action from 'forward' to 'redirect' to force all HTTP traffic on port 80 to HTTPS on port 443 using a permanent 301 redirect, ensuring encrypted communication."
}
